import{_ as a,o as n,c as t,am as s}from"./chunks/framework.CVzBg2Xv.js";const h=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),i={name:"glossaire.md"};function o(r,e,l,u,d,c){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="aipd-analyse-d-impact" tabindex="-1">AIPD (analyse d&#39;impact) <a class="header-anchor" href="#aipd-analyse-d-impact" aria-label="Permalink to &quot;AIPD (analyse d&#39;impact)&quot;">​</a></h3><p>Analyse d&#39;impact relative à la protection des données : l&#39;étude, décidée par la DPO, des risques d&#39;un traitement pour les personnes concernées, avant son lancement.</p><h3 id="arbitrage" tabindex="-1">Arbitrage <a class="header-anchor" href="#arbitrage" aria-label="Permalink to &quot;Arbitrage&quot;">​</a></h3><p>Décision entre plusieurs options qui ne tiennent pas toutes dans la capacité disponible.</p><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="bac-a-sable" tabindex="-1">Bac à sable <a class="header-anchor" href="#bac-a-sable" aria-label="Permalink to &quot;Bac à sable&quot;">​</a></h3><p>Environnement de test isolé, créé pour essayer quelque chose sans toucher à la production. Il coûte tant qu&#39;il tourne, même quand plus personne ne s&#39;en sert.</p><h3 id="business-case" tabindex="-1">Business case <a class="header-anchor" href="#business-case" aria-label="Permalink to &quot;Business case&quot;">​</a></h3><p>Dossier qui compare les options d&#39;une initiative : coûts, bénéfices attendus, risques, hypothèses et inconnues.</p><h3 id="capacite" tabindex="-1">Capacité <a class="header-anchor" href="#capacite" aria-label="Permalink to &quot;Capacité&quot;">​</a></h3><p>Quantité de travail que l&#39;équipe peut prendre dans un sprint donné, compte tenu des absences.</p><h3 id="catalogue-de-donnees" tabindex="-1">Catalogue de données <a class="header-anchor" href="#catalogue-de-donnees" aria-label="Permalink to &quot;Catalogue de données&quot;">​</a></h3><p>L&#39;inventaire des données de l&#39;entreprise : pour chacune, sa définition, son data owner, son data steward, sa source et ses règles de qualité. Une définition qu&#39;on ne trouve pas n&#39;existe pas.</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="connecteur" tabindex="-1">Connecteur <a class="header-anchor" href="#connecteur" aria-label="Permalink to &quot;Connecteur&quot;">​</a></h3><p>Logiciel qui relie deux systèmes pour qu&#39;ils échangent des données : le connecteur PMS relie Lanterne au système de gestion de l&#39;hôtel. Un outil d&#39;IA peut aussi avoir des connecteurs vers Jira, GitLab ou ServiceNow : ils ne s&#39;utilisent que s&#39;ils sont autorisés.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="data-owner" tabindex="-1">Data owner <a class="header-anchor" href="#data-owner" aria-label="Permalink to &quot;Data owner&quot;">​</a></h3><p>La personne du métier qui répond d&#39;une donnée : sa définition, la qualité attendue, qui y a accès. Une seule par donnée ; ce n&#39;est pas l&#39;équipe data.</p><h3 id="data-steward" tabindex="-1">Data steward <a class="header-anchor" href="#data-steward" aria-label="Permalink to &quot;Data steward&quot;">​</a></h3><p>La personne du métier qui connaît la donnée au quotidien : elle documente la définition, suit les règles de qualité et répond aux questions des utilisateurs.</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="dpo" tabindex="-1">DPO <a class="header-anchor" href="#dpo" aria-label="Permalink to &quot;DPO&quot;">​</a></h3><p>Délégué ou déléguée à la protection des données : la personne qui conseille et décide si un traitement de données personnelles peut être lancé, et à quelles conditions.</p><h3 id="etp" tabindex="-1">ETP <a class="header-anchor" href="#etp" aria-label="Permalink to &quot;ETP&quot;">​</a></h3><p>Équivalent temps plein : une personne à plein temps sur un an. 0,2 ETP, c&#39;est un jour par semaine.</p><h3 id="finalite" tabindex="-1">Finalité <a class="header-anchor" href="#finalite" aria-label="Permalink to &quot;Finalité&quot;">​</a></h3><p>Le but pour lequel des données personnelles sont collectées et traitées. Une donnée collectée pour un but ne sert pas à un autre sans vérifier que c&#39;est permis.</p><h3 id="finops" tabindex="-1">FinOps <a class="header-anchor" href="#finops" aria-label="Permalink to &quot;FinOps&quot;">​</a></h3><p>La pratique qui rend chaque équipe responsable de ses coûts cloud : les suivre, les expliquer, couper ce qui tourne pour rien.</p><h3 id="fuite-de-donnees" tabindex="-1">Fuite de données <a class="header-anchor" href="#fuite-de-donnees" aria-label="Permalink to &quot;Fuite de données&quot;">​</a></h3><p>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</p><h3 id="garde-fou" tabindex="-1">Garde-fou <a class="header-anchor" href="#garde-fou" aria-label="Permalink to &quot;Garde-fou&quot;">​</a></h3><p>Indicateur surveillé pour vérifier qu&#39;un progrès ne se fait pas au détriment d&#39;autre chose.</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="instructions-personnalisees-assistant-personnalise" tabindex="-1">Instructions personnalisées / assistant personnalisé <a class="header-anchor" href="#instructions-personnalisees-assistant-personnalise" aria-label="Permalink to &quot;Instructions personnalisées / assistant personnalisé&quot;">​</a></h3><p>Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).</p><h3 id="kpi" tabindex="-1">KPI <a class="header-anchor" href="#kpi" aria-label="Permalink to &quot;KPI&quot;">​</a></h3><p>Indicateur de suivi d&#39;une activité (volume, délai, taux). Tous les KPI ne sont pas des résultats clés.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>Standard pour brancher de nouveaux tools sur un assistant : applications et données de l&#39;entreprise.</p><h3 id="minimisation" tabindex="-1">Minimisation <a class="header-anchor" href="#minimisation" aria-label="Permalink to &quot;Minimisation&quot;">​</a></h3><p>Ne traiter que les données nécessaires au but poursuivi. Une donnée prise « au cas où » n&#39;est pas nécessaire.</p><h3 id="pms" tabindex="-1">PMS <a class="header-anchor" href="#pms" aria-label="Permalink to &quot;PMS&quot;">​</a></h3><p>Système de gestion de l&#39;hôtel : réservations, état des chambres, note du client.</p><h3 id="portefeuille" tabindex="-1">Portefeuille <a class="header-anchor" href="#portefeuille" aria-label="Permalink to &quot;Portefeuille&quot;">​</a></h3><p>Ensemble des produits d&#39;un même domaine, dont les priorités et les moyens sont arbitrés ensemble (ici, le portefeuille Séjour).</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="raci" tabindex="-1">RACI <a class="header-anchor" href="#raci" aria-label="Permalink to &quot;RACI&quot;">​</a></h3><p>Tableau qui dit, pour chaque activité, qui la réalise (R), qui en répond (A, une seule personne), qui est consulté (C) et qui est informé (I).</p><h3 id="rgpd" tabindex="-1">RGPD <a class="header-anchor" href="#rgpd" aria-label="Permalink to &quot;RGPD&quot;">​</a></h3><p>Règlement général sur la protection des données : le règlement européen qui encadre le traitement des données personnelles.</p><h3 id="roadmap-feuille-de-route" tabindex="-1">Roadmap (feuille de route) <a class="header-anchor" href="#roadmap-feuille-de-route" aria-label="Permalink to &quot;Roadmap (feuille de route)&quot;">​</a></h3><p>Ce que l&#39;équipe prévoit de faire maintenant, ensuite et plus tard, et pourquoi.</p><h3 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h3><p>La part du travail d&#39;une équipe data qui fait tourner l&#39;existant : surveillance des pipelines, incidents, demandes d&#39;accès, petites corrections. Elle se planifie comme le reste.</p><h3 id="self-service-bi" tabindex="-1">Self-service BI <a class="header-anchor" href="#self-service-bi" aria-label="Permalink to &quot;Self-service BI&quot;">​</a></h3><p>Des tableaux de bord et des données que les équipes du métier utilisent elles-mêmes, sans passer par l&#39;équipe data à chaque question.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="seuil-de-rentabilite" tabindex="-1">Seuil de rentabilité <a class="header-anchor" href="#seuil-de-rentabilite" aria-label="Permalink to &quot;Seuil de rentabilité&quot;">​</a></h3><p>La valeur d&#39;une hypothèse (des heures économisées, un taux) à partir de laquelle un projet rapporte plus qu&#39;il ne coûte. Il dit ce qu&#39;il faut mesurer.</p><h3 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h3><p>Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l&#39;assistant charge <strong>à la demande</strong>, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d&#39;« Agent Skills » ; d&#39;autres assistants ont des équivalents.</p><h3 id="sponsor" tabindex="-1">Sponsor <a class="header-anchor" href="#sponsor" aria-label="Permalink to &quot;Sponsor&quot;">​</a></h3><p>La personne du métier qui porte une demande, en attend une décision et en arbitre le contenu.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (tool calling).</p>',83)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
